  Object.assign(profiles[1], { agency: 'National design bureaux and scientific space institutions', startingSituation: 'The Soviet Union begins with crewed orbital flight, automatic docking, lunar and planetary probe heritage. N1 heavy lift and a crewed lunar landing remain unfinished programmes.', inheritedInfrastructure: ['Crewed orbital spacecraft and mission control', 'Automatic docking demonstrated in 1967', 'Luna and Venera engineering teams', 'Deep-space tracking and launch infrastructure'], strategicFocus: ['Salyut and Almaz', 'Robotic lunar and Venus exploration', 'Heavy-lift reliability recovery'], sourceUrls: [sources.stations.url, sources.autodock.url, sources.moon.url, sources.venus.url] });
  for (const p of profiles) Object.assign(p, { playerControlled: true, isAI: false });
  const programmes = [];
  function add(p) {
    // Proposed recurring transfer opportunities, deliberately not an ephemeris.
    const window = p.region === 'mars' ? { windowCycleMonths: 26, windowOffsetMonths: 16, windowOpenMonths: 2 }
      : p.region === 'venus' ? { windowCycleMonths: 19, windowOffsetMonths: 7, windowOpenMonths: 2 } : {};
    const commissioning = ['tracking-network', 'propulsion-qualification'].includes(p.id)
      ? { commissioningOnly: true, flightMonths: 0, missionCostB: 0, pLaunch: 1 } : {};
    const base = {
      kind: 'historical', minYear: 1970, upkeepB: 0.8, prerequisites: [], capabilityRequirements: [], grants: [], flightMonths: 0.2,
      missionCostB: 2, pLaunch: 0.90, pObjective: 0.88, prestige: 15, initialProgress: {}, owners: [],
      options: [
        { label: 'Conservative qualification', detail: 'Prioritise independent testing, redundancy and measured readiness. Additional funding cannot remove the engineering calendar.' },
        { label: 'Standard national programme', detail: 'Maintain the planned funding, qualification schedule and mission architecture.' },
        { label: 'Accelerated qualification', detail: 'Use a costly parallel development effort. Limited calendar savings must be weighed against technical and political risk.' }
      ]
    };
    programmes.push({ ...base, ...window, ...p, ...commissioning,
      baselineDurationMonths: p.durationMonths,
      durationMonths: p.durationMonths * pacing.developmentScale,
      sourceUrls: p.refs.map(k => sources[k].url) });
  }
  add({ id: 'tracking-network', name: 'Deep-Space Tracking Network', region: 'ground', durationMonths: 84, totalCostB: 24, upkeepB: 2.4, missionCostB: 0, pLaunch: 1, pObjective: 0.97, prestige: 10, grants: ['deep-space-communications'], initialProgress: { USA: 90, SOV: 78 }, owners: ['USA', 'SOV'], description: 'Expand large antennas, precision clocks, tracking ships and mission-control links. Commissioning creates national deep-space communications capacity.', historicalNote: 'Both superpowers had operational deep-space tracking in 1970. This programme represents an optional expansion and independent qualification, not the invention of radio tracking.', refs: ['pioneer10', 'taskgroup'] });
  add({ id: 'upper-stage', name: 'Restartable High-Energy Upper Stage', region: 'transfer', durationMonths: 84, totalCostB: 31, upkeepB: 0.8, missionCostB: 3, grants: ['high-energy-upper-stage'], initialProgress: { USA: 85, SOV: 76 }, owners: ['USA', 'SOV'], capabilityRequirements: ['orbital-flight'], description: 'Qualify restart sequences, coast-phase control, propellant management and precision injection. A transfer stage serves GEO, lunar and planetary missions without forcing one orbit before another.', historicalNote: 'High-energy transfer capability already existed in both 1970 programmes. This is a follow-on family and reliability upgrade.', refs: ['taskgroup', 'mercury'] });
  add({ id: 'docking-tests', name: 'Orbital Rendezvous & Docking Trials', region: 'leo', durationMonths: 60, totalCostB: 18, missionCostB: 4, grants: ['rendezvous-docking'], initialProgress: { USA: 94, SOV: 92 }, owners: ['USA', 'SOV'], capabilityRequirements: ['crewed-flight'], pObjective: 0.92, description: 'Test docking targets, relative navigation, propulsion tolerances, crew procedures and rescue compatibility in Earth orbit.', historicalNote: 'Rendezvous and docking were demonstrated before 1970. Follow-on qualification is optional; inherited national capability remains available.', refs: ['stations', 'taskgroup'] });
  add({ id: 'polar-observation', name: 'Polar Earth-Resources Observatory', region: 'polar', durationMonths: 72, totalCostB: 19, missionCostB: 3.2, upkeepB: 1.3, grants: ['earth-observation', 'polar-orbit'], initialProgress: { USA: 67, SOV: 44 }, owners: ['USA'], capabilityRequirements: ['orbital-flight'], prestige: 22, description: 'Develop multispectral instruments, image reception, calibration and national cartographic processing. Returns agriculture, water-management and survey evidence.', historicalNote: 'Landsat 1 launched in 1972. The preview inherits pre-1970 US development; the campaign timetable allocates three years to the from-scratch architecture.', refs: ['landsat', 'orbits'] });
  add({ id: 'solar-observatory', name: 'Orbital Solar & High-Energy Observatory', region: 'leo', durationMonths: 72, totalCostB: 17, missionCostB: 3, grants: ['orbital-science'], initialProgress: { USA: 55, SOV: 25 }, owners: ['USA', 'SOV'], capabilityRequirements: ['orbital-flight'], description: 'Develop solar pointing, radiation-tolerant detectors, telescope calibration and an orbital scientific operations team.', historicalNote: 'Orbital astronomy was an established Cold War scientific activity. The programme is a new instrument series, not a free pre-existing spacecraft.', refs: ['skylab', 'taskgroup'] });
  add({ id: 'geo-comsat', name: 'Geostationary Communications Network', region: 'geo', durationMonths: 84, totalCostB: 30, missionCostB: 5, upkeepB: 2.2, grants: ['geostationary-insertion', 'global-communications'], initialProgress: { USA: 72, SOV: 28 }, owners: ['USA'], capabilityRequirements: ['high-energy-upper-stage'], description: 'Build a GEO satellite bus, injection motor, ground terminals and reliable station keeping. Expansion requires replacement launches and a supported ground network.', historicalNote: 'Syncom and Early Bird preceded 1970; INTELSAT III achieved global coverage in 1969. This programme develops a follow-on national constellation.', refs: ['communications', 'orbits'] });
  add({ id: 'heo-comsat', name: 'Molniya-Type High-Latitude Communications', region: 'heo', durationMonths: 72, totalCostB: 22, missionCostB: 3.8, upkeepB: 1.8, grants: ['highly-elliptical-communications'], initialProgress: { USA: 12, SOV: 78 }, owners: ['SOV'], capabilityRequirements: ['orbital-flight', 'high-energy-upper-stage'], description: 'Develop highly elliptical spacecraft, high-latitude terminals and orbital handover schedules. The architecture trades continuous single-satellite visibility for useful high-latitude coverage.', historicalNote: 'The first successful Molniya communications satellite flew in 1965. Twelve-hour elliptical orbits offer a distinct alternative to geostationary coverage.', refs: ['molniya', 'orbits'] });
  add({ id: 'meo-navigation', name: 'Satellite Navigation & Precision Timing', region: 'meo', durationMonths: 108, totalCostB: 48, missionCostB: 7, upkeepB: 3.2, grants: ['orbital-navigation'], initialProgress: { USA: 48, SOV: 27 }, owners: ['USA', 'SOV'], capabilityRequirements: ['orbital-flight'], pObjective: 0.84, prestige: 35, description: 'Develop stable clocks, orbital ephemerides, receiver standards and ground correction stations. A constellation, replacement capacity and receiver adoption are required for useful national coverage.', historicalNote: 'US Transit was operational in 1964 in low polar orbit. This catalogue entry is a new precision-timing/MEO architecture; Transit heritage does not provide a completed modern navigation constellation.', refs: ['transit', 'orbits'] });
  add({ id: 'reconnaissance', name: 'Strategic Orbital Reconnaissance Network', region: 'polar', durationMonths: 96, totalCostB: 49, missionCostB: 6, upkeepB: 3.1, grants: ['orbital-reconnaissance'], initialProgress: { USA: 70, SOV: 68 }, owners: ['USA', 'SOV'], capabilityRequirements: ['polar-orbit', 'earth-observation'], prestige: 28, description: 'Integrate precision pointing, secure mission control, image recovery or relay and a continuing interpretation service. Coverage has revisit gaps and replacement costs.', historicalNote: 'Both powers operated reconnaissance spacecraft by 1970. This represents an expensive follow-on system rather than universal real-time visibility.', refs: ['orbits', 'taskgroup'] });
  add({ id: 'heavy-lift', name: 'Heavy-Lift Launch Vehicle Family', region: 'ground', durationMonths: 144, totalCostB: 116, missionCostB: 8.5, upkeepB: 3.4, pLaunch: 0.78, pObjective: 0.90, grants: ['heavy-lift'], initialProgress: { USA: 78, SOV: 62 }, owners: ['USA', 'SOV'], capabilityRequirements: ['launch-basic', 'high-energy-upper-stage'], prestige: 42, description: 'Qualify large propulsion clusters, stage structures, assembly buildings, launch pads and full-scale flight tests. A heavy-lift family does not become reliable through funding alone.', historicalNote: 'The United States inherits Saturn V capability. Soviet heavy-lift development is unfinished in 1970; the N1 did not become operational. An alternative successful family is a counterfactual outcome.', refs: ['taskgroup', 'moon'] });
  add({ id: 'propulsion-qualification', name: 'Advanced Propulsion Qualification Centre', region: 'ground', durationMonths: 96, totalCostB: 35, missionCostB: 0, upkeepB: 2.0, pLaunch: 1, pObjective: 0.95, grants: ['high-reliability-propulsion'], initialProgress: { USA: 58, SOV: 54 }, owners: ['USA', 'SOV'], capabilityRequirements: ['launch-basic'], description: 'Expand long-duration engine tests, fault isolation, manufacturing inspection and high-altitude simulation. A qualified centre supports future reusable and long-coast systems.', historicalNote: 'Ground qualification is an infrastructure programme. The values here model a proposed expansion, not historical expenditure.', refs: ['tug', 'taskgroup'] });
  add({ id: 'life-support', name: 'Regenerative Life-Support Development', region: 'leo', durationMonths: 108, totalCostB: 37, missionCostB: 4.5, upkeepB: 1.6, pObjective: 0.88, grants: ['long-duration-life-support', 'regenerative-life-support'], initialProgress: { USA: 68, SOV: 70 }, owners: ['USA', 'SOV'], capabilityRequirements: ['crewed-flight'], description: 'Test atmosphere management, water recovery, biological monitoring, maintenance and emergency reserves over progressively longer orbital missions.', historicalNote: '1970 profiles inherit limited long-duration capability sufficient for early stations. Regenerative, sustained support remains a new development effort.', refs: ['stations', 'skylab'] });
  add({ id: 'automated-docking', name: 'Autonomous Rendezvous & Docking', region: 'leo', durationMonths: 84, totalCostB: 26, missionCostB: 3.6, pObjective: 0.89, grants: ['autonomous-docking'], initialProgress: { USA: 40, SOV: 84 }, owners: ['SOV', 'USA'], capabilityRequirements: ['rendezvous-docking'], description: 'Qualify radar rendezvous, abort corridors, automatic docking and uncrewed navigation. Demonstration flights establish safe cargo and modular assembly procedures.', historicalNote: 'Soviet automated docking heritage preceded 1970. Operational cargo servicing still requires a separate spacecraft and flight campaign.', refs: ['stations'] });
  add({ id: 'cargo-ferry', name: 'Uncrewed Orbital Cargo Ferry', region: 'leo', durationMonths: 96, totalCostB: 34, missionCostB: 4.8, upkeepB: 2.2, grants: ['orbital-cargo'], initialProgress: { USA: 18, SOV: 34 }, owners: ['SOV'], capabilityRequirements: ['autonomous-docking'], prestige: 24, description: 'Develop a pressurised cargo vehicle, propellant transfer interfaces, rendezvous software and disposal procedures. Each delivery consumes a vehicle and launch allocation.', historicalNote: 'Progress first serviced Salyut 6 in 1978. The 1970 Soviet profile inherits study work, not a flight-ready cargo fleet.', refs: ['stations'] });
  add({ id: 'salyut', name: 'Salyut-Type Early Orbital Station', region: 'leo', durationMonths: 120, totalCostB: 53, missionCostB: 9, upkeepB: 4.2, pLaunch: 0.88, pObjective: 0.82, grants: ['orbital-station'], initialProgress: { USA: 15, SOV: 90 }, owners: ['SOV'], capabilityRequirements: ['crewed-flight', 'rendezvous-docking', 'long-duration-life-support'], prestige: 48, description: 'Develop a single-launch station, crew transport interfaces, onboard science and finite consumable reserves. Early stations have limited life and cannot support an indefinite crew without logistics.', historicalNote: 'Salyut 1 launched in April 1971. Inherited Soviet engineering leaves roughly one year of scheduled development; mission success remains uncertain.', refs: ['stations'] });
  add({ id: 'skylab', name: 'Skylab-Type Orbital Workshop', region: 'leo', durationMonths: 120, totalCostB: 68, missionCostB: 12, upkeepB: 4.8, pLaunch: 0.91, pObjective: 0.86, grants: ['orbital-station', 'orbital-science'], initialProgress: { USA: 68, SOV: 10 }, owners: ['USA'], capabilityRequirements: ['heavy-lift', 'crewed-flight', 'rendezvous-docking', 'long-duration-life-support'], prestige: 52, description: 'Develop a large orbital workshop with solar instruments, accommodation, electrical power and crew transport. Launch damage, thermal control and repair capability remain serious mission risks.', historicalNote: 'Skylab grew from Apollo Applications and launched in May 1973. The US inherits substantial work; a new national workshop takes a decade from scratch.', refs: ['skylab'] });
  add({ id: 'modular-station', name: 'Modular Long-Duration Orbital Complex', region: 'leo', durationMonths: 180, totalCostB: 172, missionCostB: 24, upkeepB: 10.5, pObjective: 0.82, grants: ['modular-orbital-station'], minYear: 1973, owners: ['SOV', 'USA'], capabilityRequirements: ['orbital-station', 'autonomous-docking', 'orbital-cargo', 'regenerative-life-support'], prestige: 88, description: 'Develop a central module, standard docking ports, incremental science modules, cargo schedules, crew rotation and orbital maintenance. Sustained occupation requires continuing launches and operating finance.', historicalNote: 'Later Salyut and Mir demonstrated progressively more capable operations. This combined programme is a proposed long-term architecture; an early station alone does not complete it.', refs: ['stations', 'taskgroup'] });
  add({ id: 'reusable-shuttle', name: 'Reusable Crewed Orbital Transport', region: 'leo', durationMonths: 156, totalCostB: 192, missionCostB: 12, upkeepB: 8.6, pLaunch: 0.86, pObjective: 0.89, grants: ['reusable-flight'], initialProgress: { USA: 15, SOV: 4 }, owners: ['USA', 'SOV'], capabilityRequirements: ['crewed-flight', 'heavy-lift', 'high-reliability-propulsion'], prestige: 76, description: 'Develop ascent systems, thermal protection, reusable engines, flight software, landing and a refurbishment infrastructure. Reuse reduces selected hardware replacement, while inspection and launch costs continue.', historicalNote: 'The US Shuttle was approved in 1972 and first flew in 1981. Soviet reusable transport followed later; the preview permits technically qualified alternate national programmes.', refs: ['shuttle', 'shuttleflight'] });
  add({ id: 'orbital-tug', name: 'Reusable Orbital Transfer Tug', region: 'transfer', kind: 'plausible', durationMonths: 132, totalCostB: 75, missionCostB: 8, upkeepB: 3.7, minYear: 1975, pLaunch: 0.88, pObjective: 0.78, grants: ['orbital-transfer-tug'], capabilityRequirements: ['high-energy-upper-stage', 'rendezvous-docking', 'high-reliability-propulsion'], prestige: 55, description: 'Develop restartable orbital propulsion, autonomous capture, thermal control and service interfaces. A tug moves a limited payload; it needs propellant, docking compatibility and replacement support.', historicalNote: 'Space tugs were studied around 1970–71 and in the 1969 Space Task Group report. This is an expensive alternate implementation, not an operational 1970 vehicle.', refs: ['tug', 'taskgroup'] });
  add({ id: 'cryogenic-storage', name: 'Long-Duration Cryogenic Propellant Storage', region: 'leo', kind: 'plausible', durationMonths: 132, totalCostB: 58, missionCostB: 8, upkeepB: 2.6, minYear: 1975, pObjective: 0.76, grants: ['cryogenic-storage'], capabilityRequirements: ['high-energy-upper-stage', 'high-reliability-propulsion'], prestige: 44, description: 'Test insulation, boil-off management, transfer couplings, fluid measurement and contamination control in orbit. Ground tanks alone do not qualify a zero-gravity propellant transfer system.', historicalNote: 'Orbital depot studies existed in 1971. Long-duration storage and transfer are unresolved engineering work in this alternative path.', refs: ['depot'] });
  add({ id: 'orbital-depot', name: 'Orbital Propellant Depot Demonstrator', region: 'transfer', kind: 'plausible', durationMonths: 180, totalCostB: 136, missionCostB: 19, upkeepB: 7.8, minYear: 1980, pLaunch: 0.87, pObjective: 0.74, grants: ['orbital-refuelling'], capabilityRequirements: ['cryogenic-storage', 'autonomous-docking', 'orbital-cargo'], prestige: 78, description: 'Assemble a storage platform, delivery vehicles, transfer plumbing and rendezvous procedures. Replenishment flights and boil-off losses remain substantial operating costs.', historicalNote: 'NASA contractor studies considered Earth- and lunar-orbit depots in 1971. The study did not create a flight-qualified or funded operational depot.', refs: ['depot', 'taskgroup'] });
  add({ id: 'space-telescope', name: 'Large Earth-Orbiting Space Telescope', region: 'leo', durationMonths: 180, totalCostB: 98, missionCostB: 14, upkeepB: 4.6, minYear: 1970, pObjective: 0.82, grants: ['precision-orbital-astronomy'], initialProgress: { USA: 12, SOV: 5 }, owners: ['USA'], capabilityRequirements: ['orbital-science', 'high-reliability-propulsion'], prestige: 68, description: 'Develop precision optics, detector calibration, low-vibration pointing, thermal control and a scientific operations centre. An optical fault may require a costly servicing mission.', historicalNote: 'Hubble was funded in 1977, launched in 1990 and repaired in 1993. The telescope belongs in Earth orbit; Sun–Earth L2 is a separate architecture.', refs: ['hubble'] });
  add({ id: 'lunar-orbiter', name: 'Lunar Mapping & Polar Survey Orbiter', region: 'moon', durationMonths: 84, totalCostB: 29, missionCostB: 5.5, flightMonths: 0.3, pObjective: 0.86, grants: ['lunar-mapping'], initialProgress: { USA: 72, SOV: 74 }, owners: ['USA', 'SOV'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 33, description: 'Qualify lunar-orbit insertion, mapping instruments, navigation and long-range links. Surface maps improve later mission planning without making this orbiter a universal prerequisite.', historicalNote: 'Both powers flew lunar orbiters before 1970. This is a new polar survey generation, with inherited technical work.', refs: ['moon'] });
  add({ id: 'lunar-rover', name: 'Robotic Lunar Rover Expedition', region: 'moon', durationMonths: 108, totalCostB: 47, missionCostB: 8, flightMonths: 0.3, pObjective: 0.77, grants: ['robotic-lunar-surface'], initialProgress: { USA: 15, SOV: 91 }, owners: ['SOV'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 52, description: 'Develop descent propulsion, hazard tolerance, teleoperation, thermal survival and a mobile science package. Landing success and useful surface operation are separate mission objectives.', historicalNote: 'Lunokhod 1 reached the Moon in November 1970. The Soviet profile inherits most development; another nation must qualify its own landing and rover hardware.', refs: ['moon'] });
  add({ id: 'lunar-sample-return', name: 'Robotic Lunar Sample Return', region: 'moon', durationMonths: 120, totalCostB: 61, missionCostB: 10, flightMonths: 0.5, pObjective: 0.70, grants: ['robotic-sample-return'], initialProgress: { USA: 18, SOV: 93 }, owners: ['SOV'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 64, description: 'Develop landing, drilling, surface ascent, Earth-return guidance and a recoverable sample capsule. Each stage may leave a scientifically useful partial success without returning material.', historicalNote: 'Luna 16 returned samples in September 1970, after earlier failures. Sample return is a demanding independent robotic branch.', refs: ['moon'] });
  add({ id: 'circumlunar-flight', name: 'Extended Crewed Circumlunar Flight', region: 'transfer', durationMonths: 120, totalCostB: 94, missionCostB: 15, flightMonths: 0.5, pLaunch: 0.91, pObjective: 0.84, grants: ['crewed-cislunar-operations'], initialProgress: { USA: 82, SOV: 70 }, owners: ['USA', 'SOV'], capabilityRequirements: ['crewed-flight', 'high-energy-upper-stage', 'deep-space-communications', 'long-duration-life-support'], prestige: 58, description: 'Qualify a longer lunar-distance crew mission, navigation, radiation monitoring, abort planning and high-speed Earth return. It does not itself deliver a lunar lander.', historicalNote: 'Apollo 8 orbited the Moon in 1968. Soviet Zond circumlunar tests did not establish an operational crewed lunar service. This is a follow-on campaign.', refs: ['moon', 'taskgroup'] });
  add({ id: 'lunar-expedition', name: 'Crewed Lunar Landing Expedition', region: 'moon', durationMonths: 156, totalCostB: 226, missionCostB: 28, upkeepB: 3.2, flightMonths: 0.5, pLaunch: 0.90, pObjective: 0.83, grants: ['lunar-landing', 'lunar-return'], initialProgress: { USA: 96, SOV: 62 }, owners: ['USA', 'SOV'], capabilityRequirements: ['heavy-lift', 'crewed-flight', 'rendezvous-docking', 'high-energy-upper-stage', 'deep-space-communications'], prestige: 90, description: 'Develop and qualify a complete lunar expedition: transfer, lunar orbit, descent, ascent, docking and safe Earth recovery. Every expedition consumes substantial launch and flight hardware.', historicalNote: 'The United States had already landed crews in 1969. A 1970 US success is a new expedition, never a second historical first. Soviet heavy-lift and landing capabilities remain unfinished.', refs: ['moon'] });
  add({ id: 'lunar-orbit-station', name: 'Lunar Orbital Science Station', region: 'moon', kind: 'plausible', durationMonths: 192, totalCostB: 186, missionCostB: 27, upkeepB: 10.8, minYear: 1980, flightMonths: 1, pLaunch: 0.88, pObjective: 0.75, grants: ['lunar-orbital-station'], capabilityRequirements: ['heavy-lift', 'crewed-cislunar-operations', 'orbital-station', 'orbital-cargo', 'regenerative-life-support'], prestige: 105, description: 'Develop a small crew-tended lunar-orbit laboratory, deep-space maintenance, supply flights and rescue contingencies. Permanent occupation requires a separate sustained logistics commitment.', historicalNote: 'Lunar-orbit stations appeared in post-Apollo planning. This is a costly alternative architecture, not a required stop before surface exploration.', refs: ['taskgroup', 'depot'] });
  add({ id: 'lunar-outpost', name: 'Crew-Tended Lunar Surface Outpost', region: 'moon', kind: 'plausible', durationMonths: 240, totalCostB: 368, missionCostB: 45, upkeepB: 18, minYear: 1980, flightMonths: 1, pLaunch: 0.88, pObjective: 0.68, grants: ['lunar-outpost'], capabilityRequirements: ['heavy-lift', 'lunar-landing', 'lunar-return', 'orbital-cargo', 'regenerative-life-support'], prestige: 150, description: 'Develop landed habitat modules, power, radiation protection, surface logistics, spares and recurring crew transport. Initial crews visit seasonally; continuous occupation is a further major commitment.', historicalNote: 'A lunar base was a post-Apollo proposal. The preview models ten campaign years of new engineering and expensive logistics; no lunar resources are automatically produced.', refs: ['taskgroup'] });
  add({ id: 'em-l2-relay', name: 'Earth–Moon L2 Far-Side Relay', region: 'em-lagrange', kind: 'plausible', durationMonths: 144, totalCostB: 72, missionCostB: 11, upkeepB: 3.7, minYear: 1985, flightMonths: 2, pObjective: 0.78, grants: ['lunar-farside-relay'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'high-reliability-propulsion'], prestige: 56, description: 'Develop a lunar-distance relay, halo-orbit navigation, large antennas and sustained station keeping to support far-side science. The mission does not operate at Sun–Earth L2.', historicalNote: 'A 1994 study examined Earth–Moon L2 relay architecture. Its inclusion is a later plausible extension with substantial qualification, not a 1970 operational system.', refs: ['emrelay', 'lagrange'] });
  add({ id: 'se-l1-observatory', name: 'Sun–Earth L1 Solar-Wind Observatory', region: 'se-l1', durationMonths: 96, totalCostB: 36, missionCostB: 6.5, upkeepB: 1.7, flightMonths: 3.5, pObjective: 0.84, grants: ['solar-wind-monitoring'], initialProgress: { USA: 14, SOV: 4 }, owners: ['USA'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 45, description: 'Develop solar-wind instruments, halo-orbit injection, long-range tracking and station keeping. The Sun–Earth L1 region is roughly 1.5 million km sunward from Earth.', historicalNote: 'ISEE-3 entered a Sun–Earth L1 halo orbit in 1978. Its transfer took about 100 days; a short cruise does not replace years of spacecraft development.', refs: ['isee', 'lagrange'] });
  add({ id: 'se-l2-observatory', name: 'Sun–Earth L2 Infrared Observatory', region: 'se-l2', kind: 'plausible', durationMonths: 204, totalCostB: 136, missionCostB: 19, upkeepB: 5.5, minYear: 1985, flightMonths: 4, pObjective: 0.77, grants: ['deep-space-infrared-astronomy'], capabilityRequirements: ['precision-orbital-astronomy', 'cryogenic-storage', 'deep-space-communications', 'high-energy-upper-stage'], prestige: 96, description: 'Develop cryogenic detectors, passive thermal geometry, precision pointing and distant autonomous servicing procedures. The Sun–Earth L2 region lies beyond Earth, away from the Sun.', historicalNote: 'Herschel/FIRST was proposed in 1982 and launched in 2009. The preview offers an alternate late-century programme, with a long development calendar and no automatic readiness at its date gate.', refs: ['herschel', 'lagrange'] });
  add({ id: 'venus-entry', name: 'Venus Atmospheric Entry & Surface Probe', region: 'venus', durationMonths: 108, totalCostB: 44, missionCostB: 8, flightMonths: 5, pObjective: 0.70, grants: ['venus-entry'], initialProgress: { USA: 38, SOV: 93 }, owners: ['SOV', 'USA'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 54, description: 'Develop a protected entry vehicle, pressure vessel, descent instruments and rapid data transmission. Atmospheric science may succeed even when surface contact is brief or absent.', historicalNote: 'Venera 7 returned the first data from another planet’s surface in 1970. Venera heritage reduces Soviet remaining engineering; surface survival remains difficult.', refs: ['venus'] });
  add({ id: 'venus-orbiter', name: 'Venus Orbital Radar & Atmospheric Survey', region: 'venus', durationMonths: 120, totalCostB: 63, missionCostB: 11, upkeepB: 2.1, flightMonths: 7, pObjective: 0.81, grants: ['venus-orbital-science'], initialProgress: { USA: 30, SOV: 34 }, owners: ['USA', 'SOV'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 62, description: 'Develop orbital insertion, radar mapping, thermal control and long-lived communications. An orbiter is a different technical branch from a short-lived surface probe.', historicalNote: 'Pioneer Venus and later Soviet radar orbiters demonstrated different approaches. A successful entry probe does not automatically qualify orbital radar hardware.', refs: ['venus'] });
  add({ id: 'mars-orbiter', name: 'Mars Orbital Reconnaissance Mission', region: 'mars', durationMonths: 108, totalCostB: 53, missionCostB: 9.5, upkeepB: 2.0, flightMonths: 9, pObjective: 0.81, grants: ['mars-orbital-science'], initialProgress: { USA: 88, SOV: 88 }, owners: ['USA', 'SOV'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 64, description: 'Develop Mars-orbit insertion, imaging, navigation and a sustained science operation. Launch-window delays and dust conditions can alter the mission without destroying all scientific value.', historicalNote: 'US and Soviet Mars orbiters arrived in 1971. Substantial pre-1970 engineering is inherited; new architectures need a long independent development.', refs: ['viking', 'windows'] });
  add({ id: 'mars-lander', name: 'Mars Surface Science Lander', region: 'mars', durationMonths: 144, totalCostB: 102, missionCostB: 17, upkeepB: 2.4, flightMonths: 10, pObjective: 0.60, grants: ['mars-surface-science'], initialProgress: { USA: 50, SOV: 90 }, owners: ['USA', 'SOV'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 90, description: 'Develop entry, descent, landing, sterilisation, power and surface science. Landing, short surface contact and a complete operating season are different outcomes.', historicalNote: 'Mars 3 made brief surface contact in 1971; Viking launched in 1975 and landed in 1976. A completed descent is not automatically a long-lived scientific success.', refs: ['viking', 'windows'] });
  add({ id: 'jupiter-flyby', name: 'Jupiter Pioneer Flyby', region: 'outer', durationMonths: 108, totalCostB: 48, missionCostB: 9, upkeepB: 1.7, flightMonths: 22, pObjective: 0.82, grants: ['outer-planet-navigation'], initialProgress: { USA: 76, SOV: 8 }, owners: ['USA'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 70, description: 'Develop long-life power, radiation protection, weak-signal communications and outer-planet navigation. Useful science arrives after a multi-year cruise.', historicalNote: 'Pioneer 10 launched in 1972 and reached Jupiter in December 1973. Pioneer 11 continued from Jupiter to Saturn, arriving there in 1979.', refs: ['pioneer10', 'pioneer11'] });
  add({ id: 'grand-tour', name: 'Outer-Planet Gravity-Assist Campaign', region: 'outer', durationMonths: 144, totalCostB: 112, missionCostB: 19, upkeepB: 2.6, flightMonths: 30, pObjective: 0.77, grants: ['outer-planet-gravity-assists'], initialProgress: { USA: 42, SOV: 4 }, owners: ['USA'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 110, description: 'Develop a long-lived probe, precision encounters, autonomous fault management and a series of gravity assists. Initial arrival resolves the first giant-planet encounter; later milestones require additional cruise years.', historicalNote: 'Voyager launched in 1977, reached Jupiter in 1979 and Saturn in 1980–81. Voyager 2 did not reach Uranus until 1986 or Neptune until 1989; the initial success never grants all later encounters at once.', refs: ['voyager'] });
  add({ id: 'mercury-flyby', name: 'Venus-Assisted Mercury Flyby', region: 'mercury', durationMonths: 108, totalCostB: 55, missionCostB: 9, upkeepB: 1.4, flightMonths: 5, pObjective: 0.78, grants: ['inner-planet-gravity-assists'], initialProgress: { USA: 62, SOV: 8 }, owners: ['USA'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 66, description: 'Develop a heat-tolerant probe, Venus gravity assist, precision navigation and short high-value Mercury encounters. This is a flyby mission rather than a Mercury orbiter.', historicalNote: 'Mariner 10 launched in November 1973, flew past Venus in February 1974 and then Mercury. Gravity assistance opened a distinct inner-planet branch.', refs: ['mercury'] });
  add({ id: 'nuclear-thermal', name: 'Nuclear Thermal Propulsion Flight Demonstrator', region: 'transfer', kind: 'cancelled', durationMonths: 180, totalCostB: 154, missionCostB: 23, upkeepB: 5.2, minYear: 1970, pLaunch: 0.82, pObjective: 0.65, grants: ['nuclear-thermal-flight'], initialProgress: { USA: 32, SOV: 10 }, owners: ['USA', 'SOV'], capabilityRequirements: ['heavy-lift', 'high-reliability-propulsion', 'deep-space-communications'], prestige: 100, description: 'Develop a nuclear propulsion stage, reactor controls, shielding, ground safety infrastructure and an uncrewed in-space test. Successful ground firing is substantial evidence but does not qualify a complete flight vehicle.', historicalNote: 'NERVA achieved ground tests and was cancelled in 1973 before flight. Completing a flight demonstrator is an alternate history programme with additional cost, political exposure and technical risk.', refs: ['nerva', 'taskgroup'] });
  add({ id: 'almaz', name: 'Almaz Crewed Reconnaissance Station', region: 'leo', durationMonths: 144, totalCostB: 86, missionCostB: 14, upkeepB: 6.1, pLaunch: 0.87, pObjective: 0.78, grants: ['orbital-station', 'orbital-reconnaissance'], initialProgress: { USA: 8, SOV: 73 }, owners: ['SOV'], capabilityRequirements: ['crewed-flight', 'rendezvous-docking', 'long-duration-life-support'], prestige: 58, description: 'Develop a crewed military reconnaissance station, optical instruments, secure downlinks, film-return procedures and its crew transport. Crewed intelligence has political visibility, finite endurance and high recurring cost.', historicalNote: 'Almaz military stations flew under the Salyut name. Salyut 2 failed in 1973; Salyut 3 flew in 1974 and Salyut 5 in 1976. Military station development is an alternative to civilian orbital science.', refs: ['stations'] });
  add({ id: 'apollo-soyuz', name: 'Apollo–Soyuz Joint Docking & Rescue Programme', region: 'leo', durationMonths: 84, totalCostB: 38, missionCostB: 8, upkeepB: 1.5, pLaunch: 0.94, pObjective: 0.91, grants: ['international-docking-standard', 'joint-orbital-rescue'], initialProgress: { USA: 26, SOV: 26 }, owners: ['USA', 'SOV'], capabilityRequirements: ['crewed-flight', 'rendezvous-docking'], prestige: 54, description: 'Develop a compatible docking adapter, atmosphere-transfer procedures, joint tracking, crew training and rescue doctrine. A bilateral flight needs negotiated partners; national hardware alone cannot create a diplomatic agreement.', historicalNote: 'Apollo–Soyuz flew in July 1975. Its engineering and diplomacy supported compatibility across two different crewed-flight systems.', refs: ['gemini', 'stations'] });
  add({ id: 'n1-l3-recovery', name: 'N1–L3 Reliability Recovery & Lunar Continuation', region: 'moon', kind: 'cancelled', durationMonths: 180, totalCostB: 244, missionCostB: 31, upkeepB: 5.8, pLaunch: 0.68, pObjective: 0.70, grants: ['heavy-lift', 'lunar-landing', 'lunar-return'], initialProgress: { USA: 2, SOV: 63 }, owners: ['SOV'], capabilityRequirements: ['launch-basic', 'crewed-flight', 'rendezvous-docking', 'high-energy-upper-stage', 'deep-space-communications'], prestige: 105, description: 'Rebuild an unsuccessful super-heavy launch programme through engine testing, cluster control, independent quality assurance and new full-scale flights. Continue lander and lunar-return qualification only after credible launch evidence.', historicalNote: 'The N1 never completed a successful launch, and the N1–L3 programme was cancelled. A reliable launcher and successful crewed landing are costly counterfactual outcomes, not inherited Soviet capabilities.', refs: ['taskgroup', 'moon'] });
  add({ id: 'energia-buran', name: 'Energia–Buran Heavy Orbital Transport', region: 'leo', durationMonths: 144, totalCostB: 218, missionCostB: 18, upkeepB: 10.1, minYear: 1976, pLaunch: 0.84, pObjective: 0.86, grants: ['heavy-lift', 'reusable-flight', 'automated-orbital-landing'], owners: ['SOV'], capabilityRequirements: ['launch-basic', 'crewed-flight', 'high-reliability-propulsion'], prestige: 86, description: 'Develop a super-heavy launch system, large winged orbiter, autonomous re-entry and a national processing infrastructure. A successful uncrewed demonstration does not certify regular crew transport or an economic reusable service.', historicalNote: 'Buran made one uncrewed orbital flight in November 1988. Energia also supported a separate heavy-payload architecture. Sustained operations after the demonstration are an alternative continuation.', refs: ['shuttleflight', 'taskgroup'] });
  add({ id: 'vega', name: 'Vega Venus Balloon & Comet Encounter', region: 'venus', durationMonths: 156, totalCostB: 89, missionCostB: 15, upkeepB: 2.1, flightMonths: 16, pObjective: 0.76, grants: ['venus-entry', 'planetary-balloon-science', 'comet-encounter-science'], initialProgress: { USA: 2, SOV: 12 }, owners: ['SOV'], capabilityRequirements: ['high-energy-upper-stage', 'deep-space-communications', 'planetary-probes'], prestige: 88, description: 'Develop a Venus entry package, atmospheric balloon, multi-national instruments and a continuing comet flyby trajectory. Balloon deployment and the later encounter are distinct objectives of one demanding flight architecture.', historicalNote: 'The Vega spacecraft launched in 1984, delivered Venus landers and balloons in 1985 and encountered Halley’s Comet in 1986. The full mission has a narrow target opportunity; this preview uses a simplified repeating Venus window.', refs: ['venus', 'windows'] });
  add({ id: 'apollo-applications', name: 'Extended Apollo Applications Workshop Campaign', region: 'leo', kind: 'cancelled', durationMonths: 144, totalCostB: 124, missionCostB: 20, upkeepB: 7.3, pLaunch: 0.91, pObjective: 0.85, grants: ['orbital-station', 'orbital-science', 'extended-workshop-campaign'], initialProgress: { USA: 38, SOV: 2 }, owners: ['USA'], capabilityRequirements: ['heavy-lift', 'crewed-flight', 'rendezvous-docking', 'long-duration-life-support'], prestige: 74, description: 'Retain heavy-launch production and develop successive orbital workshops, crew rotations, solar astronomy and Earth-observation campaigns. Workshop replacement and expedition hardware remain recurring costs.', historicalNote: 'Apollo Applications was reduced to the Skylab programme. This entry preserves and expands the abandoned workshop campaign; it is a cancelled-plan continuation, distinct from historically flown Skylab.', refs: ['skylab', 'taskgroup'] });
  // IMPERIA CW — Cold War: universal player entry, with independent and foreign-launch paths.
  add({ id: 'space-commission', name: 'Establish a National Space Commission', region: 'ground', kind: 'plausible', entryProgramme: true, durationMonths: 36, totalCostB: 0.25, upkeepB: 0.025, commissioningOnly: true, flightMonths: 0, missionCostB: 0, pLaunch: 1, pObjective: 1, grants: ['space-administration'], prestige: 3, description: 'Establish a civilian coordinating commission, national scientific priorities, procurement rules and a small programme office. Any player-controlled country may begin without inherited space hardware.', historicalNote: 'National space institutions developed through different ministries, research councils and commissions. This is a reusable institutional entry decision rather than a claim that every nation had a space agency in 1970.', refs: ['india', 'brazil', 'isis'] });
  add({ id: 'sounding-range', name: 'Sounding-Rocket Research & Range', region: 'ground', kind: 'plausible', entryProgramme: true, durationMonths: 72, totalCostB: 1.1, upkeepB: 0.08, commissioningOnly: true, flightMonths: 0, missionCostB: 0, pLaunch: 1, pObjective: 0.94, grants: ['sounding-rockets'], capabilityRequirements: ['space-administration'], prestige: 8, description: 'Develop suborbital scientific rockets, range safety, telemetry and payload-recovery procedures. Sounding flights build teams and evidence without establishing orbital launch capability.', historicalNote: 'Thumba, Esrange and Barreira do Inferno illustrate realistic sounding-research entry paths. This campaign qualifies a small research service; it does not grant an orbital rocket.', refs: ['india', 'esrange', 'brazil'] });
  add({ id: 'satellite-engineering', name: 'Satellite Payload & Bus Engineering', region: 'ground', kind: 'plausible', entryProgramme: true, durationMonths: 72, totalCostB: 0.85, upkeepB: 0.06, commissioningOnly: true, flightMonths: 0, missionCostB: 0, pLaunch: 1, pObjective: 0.96, grants: ['satellite-engineering', 'scientific-instruments'], capabilityRequirements: ['space-administration'], prestige: 8, description: 'Develop a modest spacecraft bus, power supply, scientific instrument package, environmental testing and ground acceptance. A qualified payload still needs a purchased or national launch.', historicalNote: 'Canada, Italy and West Germany built national scientific spacecraft that used foreign rockets. Satellite engineering is deliberately separate from indigenous launch qualification.', refs: ['isis', 'sanmarco', 'azur'] });
  add({ id: 'foreign-launch-partnership', name: 'Foreign Launch Partnership & First Satellite', region: 'leo', kind: 'plausible', entryProgramme: true, durationMonths: 36, totalCostB: 0.35, missionCostB: 0.12, upkeepB: 0.055, pLaunch: 0.94, pObjective: 0.91, grants: ['contracted-orbital-access', 'orbital-flight'], capabilityRequirements: ['space-administration', 'satellite-engineering', 'ground-tracking'], prestige: 15, description: 'Contract a launch provider, qualify interfaces and launch a small national spacecraft. This establishes foreign-provider orbital access and mission operations without creating a domestic rocket industry.', historicalNote: 'Alouette/ISIS, San Marco and AZUR provide historical precedents. Political cooperation and launch procurement are modelled as a funded player programme; no independent launcher is required.', refs: ['isis', 'sanmarco', 'azur'] });
  add({ id: 'indigenous-small-launcher', name: 'Independent Small Orbital Launcher', region: 'ground', kind: 'plausible', entryProgramme: true, durationMonths: 144, totalCostB: 6.5, missionCostB: 0.6, upkeepB: 0.25, pLaunch: 0.76, pObjective: 0.88, grants: ['launch-basic', 'orbital-flight'], capabilityRequirements: ['space-administration', 'sounding-rockets', 'satellite-engineering', 'ground-tracking'], prestige: 27, description: 'Qualify multi-stage propulsion, guidance, payload separation, range safety and full orbital flight. A national launcher is a long, expensive strategic choice alongside purchased launch access.', historicalNote: 'Diamant, Black Arrow, Lambda and India’s SLV illustrate distinct national development paths. Completing a sounding rocket or hiring a foreign launcher does not complete this engineering.', refs: ['diamant', 'blackarrow', 'japanbrief', 'india'] });
  add({ id: 'ground-tracking', name: 'National Tracking & Mission-Control Station', region: 'ground', kind: 'plausible', entryProgramme: true, durationMonths: 48, totalCostB: 0.65, upkeepB: 0.05, commissioningOnly: true, flightMonths: 0, missionCostB: 0, pLaunch: 1, pObjective: 0.98, grants: ['ground-tracking'], capabilityRequirements: ['space-administration'], prestige: 6, description: 'Develop a modest tracking antenna, communications links, orbital data processing and trained mission controllers. This supports national satellites and international scientific cooperation.', historicalNote: 'Tracking and control were important national contributions even where orbital launches were purchased abroad. This is an entry station, distinct from a full Deep Space Network.', refs: ['azur', 'australia', 'isis'] });
  add({ id: 'crewed-capsule', name: 'Independent Crewed Orbital Capsule', region: 'leo', kind: 'plausible', entryProgramme: true, durationMonths: 168, totalCostB: 76, missionCostB: 11, upkeepB: 3.1, pLaunch: 0.88, pObjective: 0.83, grants: ['crewed-flight'], capabilityRequirements: ['space-administration', 'launch-basic', 'orbital-flight', 'satellite-engineering', 'ground-tracking'], prestige: 58, description: 'Develop a crew cabin, short-duration life support, escape system, heat shield, recovery operations and progressively qualified uncrewed then crewed missions. A satellite programme does not provide a crew vehicle automatically.', historicalNote: 'A reusable player pathway based on established crew-capsule engineering. Countries without inherited crewed flight must finance and qualify the capability; this is not a historical 1970 national programme for every player.', refs: ['gemini', 'stations'] });
  add({ id: 'interplanetary-probe-bus', name: 'Interplanetary Probe Bus Qualification', region: 'transfer', kind: 'plausible', entryProgramme: true, durationMonths: 108, totalCostB: 19, missionCostB: 3, upkeepB: 0.7, flightMonths: 2, pLaunch: 0.91, pObjective: 0.86, grants: ['planetary-probes'], capabilityRequirements: ['space-administration', 'satellite-engineering', 'orbital-flight', 'high-energy-upper-stage', 'deep-space-communications'], prestige: 29, description: 'Qualify an autonomous deep-space bus, thermal control, long-range communications, attitude control and cruise fault recovery on a high-energy demonstration flight.', historicalNote: 'A national Earth satellite is not already a qualified planetary probe. This common programme creates a realistic capability provider for players entering deep-space exploration.', refs: ['pioneer10', 'mercury', 'venus'] });
  // IMPERIA CW — Cold War: historically grounded national architectures, open to qualified players.
  add({ id: 'diamant-b', name: 'Diamant B & Kourou Launch Qualification', region: 'ground', durationMonths: 96, totalCostB: 7.5, missionCostB: 0.85, upkeepB: 0.45, pLaunch: 0.82, pObjective: 0.92, grants: ['launch-basic', 'orbital-flight', 'equatorial-launch-operations'], initialProgress: { FRA: 96 }, owners: ['FRA'], capabilityRequirements: ['space-administration', 'sounding-rockets', 'satellite-engineering', 'ground-tracking'], prestige: 29, description: 'Qualify the Diamant B reference architecture and a new equatorial launch site, including stage integration, range control and payload interfaces.', historicalNote: 'France had Diamant A successes before 1970. Diamant B first launched from Kourou on 10 March 1970; the French profile inherits nearly completed work without receiving a free successful flight.', refs: ['diamant'] });
  add({ id: 'black-arrow', name: 'Black Arrow & Prospero Orbital Mission', region: 'ground', durationMonths: 96, totalCostB: 6.8, missionCostB: 0.75, upkeepB: 0.35, pLaunch: 0.79, pObjective: 0.91, grants: ['launch-basic', 'orbital-flight'], initialProgress: { ENG: 60 }, owners: ['ENG'], capabilityRequirements: ['space-administration', 'sounding-rockets', 'satellite-engineering', 'ground-tracking'], prestige: 31, description: 'Qualify a compact national orbital launcher and experimental satellite, using test flights and Woomera launch cooperation. A successful launch demonstrates a limited domestic launch capability.', historicalNote: 'Black Arrow launched Prospero in October 1971 and was cancelled. Continuing production after the demonstrated mission is a player alternative rather than an inherited operational fleet.', refs: ['blackarrow', 'australia'] });
  add({ id: 'ariel-science', name: 'Ariel Scientific Satellite Campaign', region: 'leo', durationMonths: 72, totalCostB: 4.2, missionCostB: 0.65, upkeepB: 0.28, pLaunch: 0.94, pObjective: 0.91, grants: ['orbital-science'], initialProgress: { ENG: 60 }, owners: ['ENG'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 23, description: 'Develop a British scientific satellite, instrument calibration and university operations while contracting foreign launch services. A national payload can fly before a domestic rocket is ready.', historicalNote: 'Ariel 1 and 2 were US-built; Ariel 3 was the first British-built satellite in 1967. This entry is a follow-on scientific campaign, not a new global first.', refs: ['ariel'] });
  add({ id: 'lambda-ohsumi', name: 'Lambda-4S & Ohsumi Orbital Demonstration', region: 'ground', durationMonths: 84, totalCostB: 5.5, missionCostB: 0.55, upkeepB: 0.25, pLaunch: 0.80, pObjective: 0.92, grants: ['launch-basic', 'orbital-flight'], initialProgress: { JAP: 98 }, owners: ['JAP'], capabilityRequirements: ['sounding-rockets', 'satellite-engineering', 'ground-tracking'], prestige: 31, description: 'Complete an unguided solid-stage orbital demonstration through stage sequencing, spin stabilisation, separation tests and range operations.', historicalNote: 'Ohsumi first reached orbit on 11 February 1970 after earlier Lambda failures. The Japanese profile begins with almost completed hardware but no successful orbital capability.', refs: ['japan', 'japanbrief'] });
  add({ id: 'mu-science', name: 'Mu Scientific Launch Vehicle & Satellite Series', region: 'leo', durationMonths: 120, totalCostB: 16, missionCostB: 1.6, upkeepB: 0.8, pLaunch: 0.84, pObjective: 0.88, grants: ['launch-basic', 'orbital-flight', 'orbital-science'], initialProgress: { JAP: 48 }, owners: ['JAP'], capabilityRequirements: ['sounding-rockets', 'satellite-engineering', 'ground-tracking'], prestige: 37, description: 'Develop a more capable solid-propellant scientific launcher, flight control and a succession of national science satellites. Each new instrument or launch remains a further commitment.', historicalNote: 'Japanese Mu launchers supported scientific missions from the early 1970s. The architecture is separate from a free modern launch service or a completed planetary probe programme.', refs: ['japanbrief', 'japan'] });
  add({ id: 'dong-fang-hong', name: 'Long March 1 & Dong Fang Hong 1', region: 'ground', durationMonths: 96, totalCostB: 8.8, missionCostB: 0.95, upkeepB: 0.45, pLaunch: 0.84, pObjective: 0.94, grants: ['launch-basic', 'orbital-flight'], initialProgress: { CHI: 92 }, owners: ['CHI'], capabilityRequirements: ['sounding-rockets', 'satellite-engineering', 'ground-tracking'], prestige: 34, description: 'Complete the first national orbital launcher and satellite through integrated testing, launch-range qualification, tracking and payload acceptance.', historicalNote: 'Long March 1 launched Dong Fang Hong 1 in April 1970. The January 1970 profile inherits engineering progress without assuming the future launch has already succeeded.', refs: ['china'] });
  add({ id: 'recoverable-satellite', name: 'Recoverable Scientific Satellite Programme', region: 'leo', durationMonths: 120, totalCostB: 20, missionCostB: 2.6, upkeepB: 0.8, pLaunch: 0.87, pObjective: 0.77, grants: ['recoverable-satellite'], initialProgress: { CHI: 18 }, owners: ['CHI'], capabilityRequirements: ['launch-basic', 'orbital-flight', 'satellite-engineering'], prestige: 38, description: 'Develop a recoverable experiment capsule, thermal protection, de-orbit control and national recovery teams. Payload survival and successful recovery are separate from orbital insertion.', historicalNote: 'China later operated recoverable spacecraft. This is a costly follow-on development from the first-satellite architecture; recovery is not inherited from Dong Fang Hong.', refs: ['china', 'taskgroup'] });
  add({ id: 'aryabhata', name: 'Aryabhata Scientific Satellite', region: 'leo', durationMonths: 96, totalCostB: 3.8, missionCostB: 0.65, upkeepB: 0.25, minYear: 1971, pLaunch: 0.94, pObjective: 0.86, grants: ['orbital-flight', 'orbital-science'], owners: ['RAJ'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 27, description: 'Develop a modest scientific satellite, Indian instrument and operations teams, and interfaces for a foreign launch provider. The mission establishes science and operations rather than a domestic rocket.', historicalNote: 'Aryabhata launched in 1975 on a Soviet rocket. ISRO exists in 1970, while this spacecraft and the later Indian launch capability still require development.', refs: ['india'] });
  add({ id: 'slv-3', name: 'SLV-3 & Rohini Independent Launch Programme', region: 'ground', durationMonths: 168, totalCostB: 9.5, missionCostB: 0.9, upkeepB: 0.5, pLaunch: 0.76, pObjective: 0.90, grants: ['launch-basic', 'orbital-flight'], initialProgress: { RAJ: 5 }, owners: ['RAJ'], capabilityRequirements: ['sounding-rockets', 'satellite-engineering', 'ground-tracking'], prestige: 35, description: 'Develop a four-stage small launcher, guidance, integration facilities and an experimental satellite. National orbital launch remains a separate long-term project from foreign satellite access.', historicalNote: 'India’s SLV-3 achieved its first successful orbital mission in 1980. The player chooses a proposed campaign timetable; historic success is not guaranteed by a calendar date.', refs: ['india'] });
  add({ id: 'isis-science', name: 'ISIS Ionospheric Satellite Campaign', region: 'leo', durationMonths: 84, totalCostB: 5.5, missionCostB: 0.9, upkeepB: 0.35, pLaunch: 0.94, pObjective: 0.91, grants: ['orbital-science'], initialProgress: { CAN: 62 }, owners: ['CAN'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 27, description: 'Develop a follow-on ionospheric research satellite, antennas, calibration and Canadian ground operations. Launch is purchased from an established provider.', historicalNote: 'Canadian-built ISIS 1 launched on a US Delta in January 1969. This programme continues that national science heritage; it never grants Canada an indigenous orbital launcher.', refs: ['isis'] });
  add({ id: 'anik-communications', name: 'Anik-Type Domestic Communications Satellite', region: 'geo', durationMonths: 96, totalCostB: 9.5, missionCostB: 1.8, upkeepB: 0.65, pLaunch: 0.94, pObjective: 0.89, grants: ['domestic-satellite-communications', 'geostationary-operations'], initialProgress: { CAN: 38 }, owners: ['CAN'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 34, description: 'Develop a domestic communications service through procured spacecraft, provider-qualified transfer stages, northern ground terminals and broadcast operations.', historicalNote: 'Anik is a Canadian domestic communications reference architecture. Purchased spacecraft and US launch access support a national service without creating Canadian launch-vehicle production.', refs: ['isis', 'communications'] });
  add({ id: 'san-marco', name: 'San Marco Equatorial Scientific Launch Campaign', region: 'leo', durationMonths: 96, totalCostB: 7.2, missionCostB: 1.1, upkeepB: 0.6, pLaunch: 0.92, pObjective: 0.89, grants: ['orbital-science', 'offshore-launch-operations'], initialProgress: { ITA: 58 }, owners: ['ITA'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 29, description: 'Develop equatorial science missions, ocean-platform operations and Scout integration with a partner. Offshore launch geography offers a national service role without supplying a domestic rocket.', historicalNote: 'San Marco 2 launched from the Italian-operated equatorial platforms in 1967 using a US-provided Scout. The preview models a continuing mission campaign.', refs: ['sanmarco'] });
  add({ id: 'sirio', name: 'SIRIO Experimental Communications Satellite', region: 'geo', durationMonths: 108, totalCostB: 8.5, missionCostB: 1.6, upkeepB: 0.55, minYear: 1971, pLaunch: 0.94, pObjective: 0.88, grants: ['experimental-satellite-communications', 'geostationary-operations'], owners: ['ITA'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 32, description: 'Develop an experimental communications payload, propagation measurements, receiving terminals and international launch integration.', historicalNote: 'SIRIO represents Italy’s later experimental communications branch. In the 1970 profile it is a development option, not an already operational satellite.', refs: ['sanmarco', 'communications'] });
  add({ id: 'azur-science', name: 'AZUR Follow-On Radiation Science Satellite', region: 'polar', durationMonths: 84, totalCostB: 6.8, missionCostB: 1.1, upkeepB: 0.4, pLaunch: 0.94, pObjective: 0.90, grants: ['orbital-science', 'radiation-environment-science'], initialProgress: { GER: 26 }, owners: ['GER'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 28, description: 'Develop a follow-on radiation-belt science payload, experiment calibration and ground analysis using a contracted polar launch.', historicalNote: 'AZUR launched on a US Scout in November 1969 and established German spacecraft operations. This entry is a proposed follow-on campaign rather than a claim that another AZUR actually flew.', refs: ['azur'] });
  add({ id: 'symphonie', name: 'Symphonie European Communications Demonstrator', region: 'geo', durationMonths: 120, totalCostB: 14, missionCostB: 2.5, upkeepB: 0.9, pLaunch: 0.93, pObjective: 0.89, grants: ['experimental-satellite-communications', 'geostationary-operations'], initialProgress: { FRA: 40, GER: 40 }, owners: ['FRA', 'GER'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 39, description: 'Develop a cooperative European communications spacecraft, stable three-axis pointing, international terminals and partner launch procurement.', historicalNote: 'The Symphonie architecture is a bilateral Franco-German reference. Cooperation supports a spacecraft and ground-system project; it does not create a free independent European launcher.', refs: ['azur', 'communications'] });
  add({ id: 'ans-astronomy', name: 'ANS Ultraviolet & X-Ray Astronomy Satellite', region: 'leo', durationMonths: 96, totalCostB: 4.8, missionCostB: 0.85, upkeepB: 0.3, pLaunch: 0.94, pObjective: 0.90, grants: ['orbital-science', 'astronomical-instruments'], initialProgress: { HOL: 5 }, owners: ['HOL'], capabilityRequirements: ['satellite-engineering', 'contracted-orbital-access', 'ground-tracking'], prestige: 29, description: 'Develop a compact astronomical satellite, ultraviolet and X-ray instruments, precise pointing and ground analysis with an international launch provider.', historicalNote: 'ANS received Dutch approval in December 1970 and launched in 1974. January 1970 inherits scientific studies, not a funded completed spacecraft or independent rocket.', refs: ['ans', 'estec'] });
  add({ id: 'esrange-science', name: 'Esrange Polar & Auroral Research Campaign', region: 'ground', durationMonths: 72, totalCostB: 2.5, upkeepB: 0.18, commissioningOnly: true, flightMonths: 0, missionCostB: 0, pLaunch: 1, pObjective: 0.95, grants: ['sounding-rockets', 'polar-science', 'range-services'], initialProgress: { SWE: 62 }, owners: ['SWE'], capabilityRequirements: ['sounding-rockets', 'scientific-instruments', 'ground-tracking'], prestige: 19, description: 'Expand polar sounding flights, auroral instruments, tracking and international scientific range services. The campaign remains suborbital.', historicalNote: 'ESRO opened Esrange in 1966. Its 1970 heritage is treated as international sounding-research infrastructure, without inventing a Swedish orbital launcher or modern agency.', refs: ['esrange'] });
